                DyeImpurityRatio(dye="m", band="r", lo=0.00, hi=0.10),  # K^p_k
                DyeImpurityRatio(dye="c", band="b", lo=0.00, hi=0.08),  # K^g_s
                DyeImpurityRatio(dye="c", band="g", lo=0.00, hi=0.08),  # K^g_z
