        grain=GrainSpec(16.0, 13.0, 12.0, 17.0, clump_gain=0.72, fog_grain=0.17,
                        rms_r=23.0, rms_g=16.0, rms_b=34.0),
        # [T2-VISUAL] f50 READ OFF Fig. 11 (2026-08-19, queue item G3). SOURCE
